pug:
.gray-block
    .asset-logo-2
        p.asset {{ text_1 }}
        p.gray-text BTC
    .h-24 &nbsp;
    p.text.pt24.bt {{ text_2 }}

styl:
.bt { border-top: 1px solid #d9d9db; }
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pt24 { padding-top: 24px; }
.h-24 { font-size: 8px;
  line-height: 24px;
  height: 24px; }
.asset { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 18px;
  line-height: 27px;
  color: #393a44;
  color: #393a44; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
.gray-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #a6a6ab; }
.gray-block { background: #f9f9f9 url("https://fsms.quadcode.com/storage/public/d7/b1/3lansqgk5ucdfokg/right-arrow.png") top 24px right 24px no-repeat;
  background-size: 24px;
  padding: 24px;
  border-radius: 24px; }
.asset-logo-2 { background: url("https://fsms.quadcode.com/storage/public/d7/38/a4pcr7pkt9m67i1g/btc.png") center left no-repeat;
  background-size: 56px;
  padding: 5px 0;
  padding-left: 76px !important; }
